func renderTagMap(v map[string]string) string {
	parts := make([]string, 0, len(v))
	for _, k := range slices.Sorted(maps.Keys(v)) {
		e := v[k]
		parts = append(parts, k+"="+e)
	}
	return "{" + strings.Join(parts, ", ") + "}"
}

// at extends a violation path without aliasing the parent's array.
func at(p awserr.Path, segments ...string) awserr.Path { return append(slices.Clip(p), segments...) }
